<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import type {FieldDefinition} from '../../api/domain';
 import {loadModuleWorkspace,saveModuleWorkspace,type ModuleLayout,type ModuleViewKind} from '../../api/moduleViews';
 import {presetLayout,moduleView,viewNames} from '../../util/moduleViews';
 import {requestConfirmation} from '../../confirmation';
 let {moduleUid,moduleName,fields,dirty=$bindable(false)}:{moduleUid:string;moduleName:string;fields:FieldDefinition[];dirty?:boolean}=$props();
 let layout=$state<ModuleLayout>({default_view:'',views:[],sections:[]});let saved=$state('');let revision=$state(0);let busy=$state(true);let error=$state('');let notice=$state('');let preset=$state<'crm'|'erp'|'accounting'|'inventory'|'dms'|'information'>('information');let dead=false;let controller:AbortController|undefined;
 const publicFields=$derived(fields.filter(f=>f.active&&String(f.config.access_scope||'module')==='module'));
 const assigned=$derived(new Set(layout.sections.flatMap(s=>s.fields)));
 $effect(()=>{dirty=!!saved&&JSON.stringify(layout)!==saved;});
 onMount(()=>void load());onDestroy(()=>{dead=true;controller?.abort();});
 async function load(){controller?.abort();const request=new AbortController();controller=request;busy=true;error='';try{const next=await loadModuleWorkspace(moduleUid,request.signal);if(dead)return;revision=next.revision;layout=next.layout;saved=JSON.stringify(next.layout);}catch(e){if(!dead&&!request.signal.aborted)error=e instanceof Error?e.message:String(e);}finally{if(!dead)busy=false;}}
 async function applyPreset(){if(layout.views.length&&!await requestConfirmation({title:'Replace the draft layout?',description:'Only view and section settings in this draft will change. Fields, records, permissions, workflows and posted books are not modified.',confirmLabel:'Use starting layout',tone:'primary'}))return;layout=presetLayout(preset);notice='Starting layout applied to this draft. Choose fields and check its prerequisites before saving.';error='';}
 function add(){if(layout.views.length>=12)return;const view=moduleView(`view-${crypto.randomUUID().slice(0,8)}`,'cards','New view');layout.views.push(view);if(!layout.default_view)layout.default_view=view.id;}
 function remove(index:number){const id=layout.views[index].id;layout.views.splice(index,1);if(layout.default_view===id)layout.default_view=layout.views[0]?.id||'';}
 function move(index:number,direction:number){const next=index+direction;if(next<0||next>=layout.views.length)return;[layout.views[index],layout.views[next]]=[layout.views[next],layout.views[index]];}
 async function save(event:SubmitEvent){event.preventDefault();if(busy)return;busy=true;error='';notice='';try{const next=await saveModuleWorkspace(moduleUid,revision,$state.snapshot(layout));if(dead)return;revision=next.revision;layout=next.layout;saved=JSON.stringify(next.layout);notice=`Workspace saved for ${moduleName}.`;dirty=false;}catch(e){if(!dead)error=e instanceof Error?e.message:String(e);}finally{if(!dead)busy=false;}}
</script>
<form class="views-admin" onsubmit={save}>
 <header><p class="eyebrow">Module · {moduleName}</p><h2>Views & layout</h2><p>Design this module’s opening screen and available views. A starting layout is an editable arrangement—not a different application or a preconfigured business system.</p><a class="button" href={`#module/${encodeURIComponent(moduleUid)}`}>Open this module</a></header>
 <section class="layout-start"><div><h3>Choose a starting point</h3><p>CRM starts with a pipeline. ERP starts with operations. Accounting opens the ledger. Every view can be renamed, reordered or removed.</p></div><label>Starting layout<select bind:value={preset}><option value="information">Information system</option><option value="crm">CRM</option><option value="erp">ERP / operations</option><option value="accounting">Accounting</option><option value="inventory">Inventory</option><option value="dms">Document management</option></select></label><button class="button" type="button" disabled={busy} onclick={applyPreset}>Use starting layout</button></section>
 <p class="notice">Pipeline views require an enabled Process & actions. Accounting / Inventory views require their book enabled. Document libraries require a File Attachment field. Layouts never bypass record or field permissions.</p>
 {#if !layout.views.length}<p class="empty-state compact">No workspace layout has been saved. This module continues to open in its existing Records view until you save a layout.</p>{/if}
 <fieldset disabled={busy}><legend>Module views</legend><label class="opening-view">Opening view<select required bind:value={layout.default_view}><option value="">Choose opening view…</option>{#each layout.views as view}<option value={view.id}>{view.name}</option>{/each}</select></label>
 {#each layout.views as view,index (view.id)}<section class="view-definition"><header><h3>View {index+1} · {view.name}</h3><div class="button-row"><button class="button small" type="button" aria-label={`Move ${view.name} earlier`} disabled={index===0} onclick={()=>move(index,-1)}>↑</button><button class="button small" type="button" aria-label={`Move ${view.name} later`} disabled={index===layout.views.length-1} onclick={()=>move(index,1)}>↓</button><button class="button small" type="button" aria-label={`Remove ${view.name}`} onclick={()=>remove(index)}>Remove</button></div></header>
  <div class="view-grid"><label>View name<input required maxlength="60" bind:value={view.name}/></label><label>Presentation<select bind:value={view.kind}>{#each Object.entries(viewNames) as [kind,name]}<option value={kind}>{name}</option>{/each}</select></label>
  {#if ['cards','documents','overview'].includes(view.kind)}<label>Title field<select bind:value={view.title_field}><option value="">First available field</option>{#each publicFields.filter(f=>f.field_type!=='attachments') as field}<option value={field.key}>{field.label}</option>{/each}</select></label>{/if}
  <label class="full">Instructions for users<textarea rows="2" maxlength="300" bind:value={view.description} placeholder="Optional short guidance for this view"></textarea></label></div>
  {#if view.kind==='board'}<p class="muted">Columns and card titles follow Process & actions. A card opens its saved information and permitted decisions; merely dragging a card cannot approve a request.</p>{/if}
  {#if ['cards','documents','overview'].includes(view.kind)}<fieldset class="field-choices"><legend>Card information · up to eight fields</legend>{#each publicFields.filter(f=>f.field_type!=='attachments') as field}<label class="checkbox"><input type="checkbox" checked={view.fields.includes(field.key)} disabled={!view.fields.includes(field.key)&&view.fields.length>=8} onchange={e=>view.fields=e.currentTarget.checked?[...view.fields,field.key]:view.fields.filter(k=>k!==field.key)}/>{field.label}</label>{/each}</fieldset>{/if}
  {#if view.kind==='overview'}<fieldset class="field-choices"><legend>Summary tiles · up to four configured Column totals</legend>{#each publicFields.filter(f=>['integer','decimal','formula','rollup'].includes(f.field_type)&&f.config.table_summary&&f.config.table_summary!=='none') as field}<label class="checkbox"><input type="checkbox" checked={view.summary_fields.includes(field.key)} disabled={!view.summary_fields.includes(field.key)&&view.summary_fields.length>=4} onchange={e=>view.summary_fields=e.currentTarget.checked?[...view.summary_fields,field.key]:view.summary_fields.filter(k=>k!==field.key)}/>{field.label}</label>{/each}</fieldset>{/if}
 </section>{/each}<button class="button" type="button" disabled={layout.views.length>=12} onclick={add}>Add view</button></fieldset>
 <fieldset disabled={busy}><legend>Record details layout</legend><p>Group fields into named sections, in the order below. Unassigned fields remain visible under Other information. Conditional form rules and access restrictions still apply.</p>
 {#each layout.sections as section,index}<section class="record-section"><div class="section-heading"><label>Section name<input required maxlength="80" bind:value={section.name}/></label><button class="button small" type="button" aria-label={`Move section ${section.name} earlier`} disabled={index===0} onclick={()=>{[layout.sections[index-1],layout.sections[index]]=[layout.sections[index],layout.sections[index-1]];}}>↑</button><button class="button small" type="button" onclick={()=>layout.sections.splice(index,1)}>Remove section</button></div><div class="field-choices">{#each fields.filter(f=>f.active) as field}<label class="checkbox"><input type="checkbox" checked={section.fields.includes(field.key)} disabled={assigned.has(field.key)&&!section.fields.includes(field.key)} onchange={e=>section.fields=e.currentTarget.checked?[...section.fields,field.key]:section.fields.filter(k=>k!==field.key)}/>{field.label}</label>{/each}</div></section>{/each}
 <button class="button" type="button" disabled={layout.sections.length>=16} onclick={()=>layout.sections.push({name:'New section',fields:[]})}>Add record section</button></fieldset>
 <footer class="layout-save">{#if error}<p role="alert" class="notice error">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}<div><small>{dirty?'Unsaved workspace changes':`Saved workspace revision ${revision}`}</small><button class="button" type="button" disabled={busy} onclick={async()=>{if(!dirty||await requestConfirmation({title:'Discard this workspace draft?',description:'The currently saved layout will be reloaded. Records are not changed.',confirmLabel:'Reload saved layout',tone:'danger'}))void load();}}>Reload saved layout</button><button class="button primary" disabled={busy||!layout.views.length}>{busy?'Saving / loading…':'Save workspace layout'}</button></div></footer>
</form>
<style>
 .views-admin{max-width:80rem}.views-admin>header{padding:1.2rem;border:1px solid var(--line);border-radius:.75rem;background:var(--surface)}h2{font-size:1.3rem;margin:.3rem 0}h3{font-size:1rem;margin:0}p{font-size:.95rem;line-height:1.6;color:var(--muted)}.layout-start{display:flex;align-items:end;flex-wrap:wrap;gap:1rem;margin:1rem 0;padding:1rem;border:1px solid var(--line);border-radius:.65rem}.layout-start>div{flex:1;min-width:15rem}.layout-start p{margin:.4rem 0 0}.layout-start label{min-width:13rem}label{display:grid;gap:.4rem;font-size:.9rem}input,textarea,select{width:100%;min-width:0;box-sizing:border-box}.opening-view{max-width:25rem;margin:.5rem 0 1rem}fieldset{min-width:0;margin:1rem 0;border:1px solid var(--line);border-radius:.7rem;padding:1rem}legend{font-weight:650;padding:0 .5rem}.view-definition{padding:1rem;border:1px solid var(--line);border-radius:.6rem;margin-bottom:1rem;background:var(--surface)}.view-definition>header{display:flex;justify-content:space-between;gap:1rem;align-items:center;margin-bottom:1rem}.view-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.full{grid-column:1/-1}.field-choices{display:flex;flex-wrap:wrap;gap:.75rem 1.25rem}.checkbox{display:flex;align-items:center;gap:.45rem}.checkbox input{width:auto}.record-section{padding:1rem;margin:.75rem 0;border:1px solid var(--line);border-radius:.5rem;background:var(--surface)}.section-heading{display:flex;align-items:end;gap:.75rem;margin-bottom:1rem}.section-heading label{flex:1}.layout-save{position:sticky;bottom:0;padding:.8rem;background:var(--surface);border:1px solid var(--line);border-radius:.6rem;z-index:3;box-shadow:0 -3px 12px #00000008}.layout-save>div{display:flex;align-items:center;justify-content:flex-end;gap:.75rem;flex-wrap:wrap}.layout-save small{margin-right:auto;color:var(--muted)}.layout-save p{margin:.3rem 0 .75rem;color:var(--text)}@media(max-width:700px){.view-grid{grid-template-columns:1fr}.view-definition>header{flex-direction:column;align-items:start}.section-heading{flex-wrap:wrap}.section-heading label{flex-basis:100%}.layout-save>div .button{flex:1}}
</style>
